function encodeUtf8Base64(text) {
  if (typeof btoa === "function") {
    return btoa(String.fromCharCode(...new TextEncoder().encode(text)));
  }
  return Buffer.from(text, "utf8").toString("base64");
}

function makeEditorsProjectFile(editors) {
  return {
    path: "editors.json",
    kind: "editor-config",
    source: "example",
    base64: encodeUtf8Base64(JSON.stringify({ version: 1, editors }, null, 2))
  };
}


