function replaceEditorsProjectFile(id, editors) {
  derivedProjectFilesById[id] = [
    ...(derivedProjectFilesById[id] || []).filter((file) => file.path !== "editors.json"),
    makeEditorsProjectFile(editors)
  ];
}

